  Lemma disjoint_scratch_pl : forall LF m XS O n, as_RFS H LF m -> fsobj H LF O n -> aplace O n -> 0 <= n ->
    Forall (fs_scratch H LF) XS -> disjoint_from XS O n.
  Proof.
    intros LF m XS O n RF OB AP Hn FX. induction XS as [|[l h] XS IH]; cbn; [exact I|].
    split; [| apply IH; exact (Forall_inv_tail FX)].
    exact (fsobj_scratch_pl LF O n m (l, h) RF OB AP Hn (Forall_inv FX)).
  Qed.

  Lemma disjoint_scratch_sh_pl : forall LF m XS O n, as_RFS H LF m -> fsobj H LF O n -> aplace O n -> 0 <= n ->
    Forall (fs_scratch H LF) XS -> disjoint_from XS (sh O) (nsh n).
  Proof.
    intros LF m XS O n RF OB (P1 & P2 & P3 & P4) Hn FX. induction XS as [|[l h] XS IH]; cbn; [exact I|].
    split; [| apply IH; exact (Forall_inv_tail FX)].
    exact (fsobj_scratch_sh H HH LF O n m (l, h) RF OB ltac:(lia) Hn ltac:(lia) (Forall_inv FX)).
  Qed.

  Lemma Forall_scratch_pl : forall LF m XS O n, as_RFS H LF m -> fsobj H LF O n -> aplace O n -> 0 <= n ->
